// TMDB metadata, watch providers and Wikidata IDs per TMDB title.
// TMDB's own IDs are stored with UpsertTmdbTitleIDs (source tmdb).
func (q *Queries) UpsertTmdbTitleDetails(ctx context.Context, arg UpsertTmdbTitleDetailsParams) error {
	_, err := q.db.ExecContext(ctx, upsertTmdbTitleDetails,
		arg.TmdbKind,
		arg.TmdbID,
		arg.Title,
		arg.OriginalTitle,
		arg.OriginalLanguage,
		arg.Overview,
		arg.Status,
		arg.ReleaseDate,
		arg.LastAirDate,
		arg.Runtime,
		arg.NumberOfSeasons,
		arg.NumberOfEpisodes,
		arg.Genres,
		arg.OriginCountries,
		arg.ProductionCompanies,
		arg.Networks,
		arg.PosterPath,
		arg.BackdropPath,
		arg.Popularity,
		arg.VoteAverage,
		arg.VoteCount,
		arg.DigitalReleaseDates,
		arg.Seasons,
	)
	return err
}

